import React from "react";
import {AppBar,Toolbar,styled} from '@mui/material';
import logo from './editor2.png'

const Head = styled(AppBar)`
    background : #000066
    height : 9vh`


const Header = ()=>{
    return(
       <Head>
        <Toolbar>
            <img src={logo} alt="Code Pen" style={{ width: '40px',height:'40px'}}/>
        </Toolbar>
       </Head>
    )
}

export default Header;
